(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.OBCaptions=api})(typeof globalThis!=='undefined'?globalThis:this,function(){function time(value){const m=String(value).match(/^(?:(\d{2,}):)?(\d{2}):(\d{2})[.,](\d{3})$/);if(!m||+m[2]>59||+m[3]>59)throw Error('Invalid caption timestamp');return +(m[1]||0)*3600 + +m[2]*60 + +m[3] + +m[4]/1000}function plain(s){return s.replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,' ')}function parse(input){if(typeof input!=='string'||input.length>1048576)throw Error('Captions must be under 1 MiB');const blocks=input.replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').trim().split(/\n\s*\n/),cues=[];for(const block of blocks){const lines=block.split('\n');if(/^(WEBVTT|NOTE(?: |$)|STYLE$|REGION$)/.test(lines[0]))continue;const i=lines.findIndex(l=>l.includes('-->'));if(i<0)continue;const match=lines[i].match(/^\s*(\S+)\s+-->\s+(\S+)(?:\s+.*)?$/);if(!match)throw Error('Invalid caption cue');const start=time(match[1]),end=time(match[2]);if(end<=start||end>86400)throw Error('Invalid caption duration');const text=plain(lines.slice(i+1).join('\n')).trim();if(text)cues.push({start,end,text});if(cues.length>5000)throw Error('Too many caption cues')}if(!cues.length)throw Error('No readable caption cues');return cues.sort((a,b)=>a.start-b.start)}function at(cues,position){return cues.filter(c=>position>=c.start&&position<c.end).map(c=>c.text).slice(0,3).join('\n')}return {time,parse,at};});